import{_ as o,o as e,c as t,ag as r}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"12.4 音视频容量与颜色空间 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"12-数学与多媒体/04-音视频容量与颜色空间.md","filePath":"12-数学与多媒体/04-音视频容量与颜色空间.md"}'),n={name:"12-数学与多媒体/04-音视频容量与颜色空间.md"};function s(i,a,l,d,c,p){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="_12-4-音视频容量与颜色空间-★★★" tabindex="-1">12.4 音视频容量与颜色空间 ★★★ <a class="header-anchor" href="#_12-4-音视频容量与颜色空间-★★★" aria-label="Permalink to &quot;12.4 音视频容量与颜色空间 ★★★&quot;">​</a></h1><h3 id="_8-1-音频容量" tabindex="-1">8.1 音频容量 <a class="header-anchor" href="#_8-1-音频容量" aria-label="Permalink to &quot;8.1 音频容量&quot;">​</a></h3><p>未压缩 PCM 音频：</p><p><strong>容量(bit)=采样频率(次/秒)×量化位数(bit/次)×声道数×时间(秒)</strong></p><p><strong>容量(Byte)=上述结果÷8</strong></p><p>例：44.1 kHz、16 bit、双声道，录音 10 秒：</p><p><code>44100×16×2×10/8=1764000 B≈1.682 MiB</code>。</p><p>第二种方法：每次每声道 16 bit=2 B；每秒双声道 <code>44100×2×2=176400 B</code>；10 秒 <code>176400×10=1764000 B</code>，一致。</p><p><strong>反例</strong>：双声道不是把采样率翻倍，而是在同一时刻记录两个声道；计算容量时仍要额外乘 2。<code>44.1 kHz=44100 Hz</code>，不能直接把 44.1 当每秒采样次数。</p><h3 id="_8-2-采样定理" tabindex="-1">8.2 采样定理 <a class="header-anchor" href="#_8-2-采样定理" aria-label="Permalink to &quot;8.2 采样定理&quot;">​</a></h3><p>为从采样值中恢复最高频率为 fmax 的带限信号，理想情况下采样频率应满足：</p><p><strong>fs ≥ 2fmax</strong></p><p>例：语音最高频率 8 kHz，采样频率至少应为 <code>2×8=16 kHz</code>。</p><p>口诀：<strong>最高频率乘二，才不发生混叠</strong>。实际系统通常留出滤波余量，不会只卡理论等号。</p><p><strong>反向考法（fmax ≤ fs/2，必背）</strong>：把公式反过来读——<strong>采样频率一旦给定，能不失真恢复的最高频率就是 fs/2</strong>（称为奈奎斯特频率）。两种问法对应两种动作：给 fmax 求 fs → <strong>乘 2</strong>；给 fs 求&quot;能采到的最高频率&quot; → <strong>除 2</strong>。</p><p><strong>混叠算例</strong>：设采样频率 fs=8 kHz，对它采样一个最高频率 5 kHz 的正弦信号。按定理要求 fs 应 ≥ 2×5=10 kHz，8 kHz <strong>不满足</strong> → 发生<strong>混叠（频谱折叠）</strong>。恢复时 5 kHz 会&quot;折叠&quot;成 <code>|fs − f|</code>，即 <code>8−5=3</code> kHz——你恢复出来的是一个 <strong>3 kHz 的假信号</strong>。口诀：<strong>采样不够，高频折叠成 fs−f</strong>。</p><h3 id="_8-3-midi-与数字音频" tabindex="-1">8.3 MIDI 与数字音频 <a class="header-anchor" href="#_8-3-midi-与数字音频" aria-label="Permalink to &quot;8.3 MIDI 与数字音频&quot;">​</a></h3><ul><li>PCM/WAV 类采样音频保存波形样本，能记录人声和任意声音，容量较大；</li><li>MIDI 保存音符、音高、时长、乐器等演奏指令，不保存真实声音波形，容量小，但播放效果依赖音源，不能直接真实记录一段人声。</li></ul><h3 id="_8-4-未压缩视频容量" tabindex="-1">8.4 未压缩视频容量 <a class="header-anchor" href="#_8-4-未压缩视频容量" aria-label="Permalink to &quot;8.4 未压缩视频容量&quot;">​</a></h3><p><strong>视频容量(Byte)=宽×高×每像素位数×帧率×时长÷8</strong></p><p>例：<code>1280×720</code>、24 bit、25 fps、10 秒的未压缩视频：</p><p><code>1280×720×24×25×10/8=691200000 B≈659.18 MiB</code>。</p><p>反向分层验证：每帧 <code>1280×720×3=2764800 B</code>；10 秒共 <code>25×10=250</code> 帧；<code>2764800×250=691200000 B</code>。</p><p><strong>应试动作</strong>：音频写“采样率×位数×声道×秒÷8”；视频在图像公式后再乘“帧/秒×秒”。看到最高频率则乘 2 求最低采样率。</p><hr><h2 id="第九节-颜色空间-显示、印刷与视频各有一套语言-★★" tabindex="-1">第九节 颜色空间：显示、印刷与视频各有一套语言 ★★ <a class="header-anchor" href="#第九节-颜色空间-显示、印刷与视频各有一套语言-★★" aria-label="Permalink to &quot;第九节 颜色空间：显示、印刷与视频各有一套语言 ★★&quot;">​</a></h2><h3 id="_9-1-rgb-发光设备做加法" tabindex="-1">9.1 RGB：发光设备做加法 <a class="header-anchor" href="#_9-1-rgb-发光设备做加法" aria-label="Permalink to &quot;9.1 RGB：发光设备做加法&quot;">​</a></h3><p>RGB 用红（Red）、绿（Green）、蓝（Blue）三种光叠加：</p><ul><li>三者全 0 → 黑；</li><li>三者都达到最大 → 白；</li><li>适合显示器、摄像头等发光/采集设备。</li></ul><p>称为<strong>加色模型</strong>，因为加光越多越亮。</p><h3 id="_9-2-cmy-cmyk-印刷颜料做减法" tabindex="-1">9.2 CMY/CMYK：印刷颜料做减法 <a class="header-anchor" href="#_9-2-cmy-cmyk-印刷颜料做减法" aria-label="Permalink to &quot;9.2 CMY/CMYK：印刷颜料做减法&quot;">​</a></h3><p>CMY 为青（Cyan）、品红（Magenta）、黄（Yellow），颜料通过吸收一部分光形成颜色，属于<strong>减色模型</strong>。印刷常增加 K（Black，黑）形成 CMYK，以得到更纯的黑色并节省彩色墨水。</p><p><strong>反例</strong>：打印机不是把 RGB 三束光打到纸上。屏幕自身发光用 RGB；纸张反射环境光、油墨吸光，用 CMYK。</p><h3 id="_9-3-yuv-ycbcr-把亮度与色度分开" tabindex="-1">9.3 YUV/YCbCr：把亮度与色度分开 <a class="header-anchor" href="#_9-3-yuv-ycbcr-把亮度与色度分开" aria-label="Permalink to &quot;9.3 YUV/YCbCr：把亮度与色度分开&quot;">​</a></h3><ul><li>Y：亮度（luminance/luma）；</li><li>U、V 或 Cb、Cr：色度/色差信息。</li></ul><p>人眼对亮度细节比色度细节更敏感，因此视频和 JPEG 可对色度做更强压缩，减少数据而尽量保持主观质量。Y 分量还带来与黑白显示的兼容思路。</p><h3 id="_9-4-hsv-hsl-按人的颜色直觉描述" tabindex="-1">9.4 HSV/HSL：按人的颜色直觉描述 <a class="header-anchor" href="#_9-4-hsv-hsl-按人的颜色直觉描述" aria-label="Permalink to &quot;9.4 HSV/HSL：按人的颜色直觉描述&quot;">​</a></h3><p>HSV 常用 Hue（色相）、Saturation（饱和度）、Value（明度）描述颜色，便于选色与图像处理。它不是显示器物理发光的基本模型。</p><p><strong>应试动作</strong>：显示器选 RGB（加色）；印刷选 CMYK（减色）；电视/视频与亮色分离选 YUV/YCbCr；按色相、饱和度调色选 HSV/HSL。</p><hr>',40)])])}const g=o(n,[["render",s]]);export{_ as __pageData,g as default};
